import { proxyActivities } from "@temporalio/workflow";
import type * as activities from "../activities/index.js";

const { acquireSandbox, runAgent, releaseSandbox } = proxyActivities<typeof activities>({
  startToCloseTimeout: "6 hours",
  heartbeatTimeout: "2 minutes",
  retry: { maximumAttempts: 3 },
});

export async function ticketToPr(input: { ticketKey: string }): Promise<string> {
  const vm = await acquireSandbox({ size: "lite" });
  try {
    return await runAgent({ vmId: vm.id, ticketKey: input.ticketKey });
  } finally {
    await releaseSandbox({ vmId: vm.id });
  }
}

import { Context } from "@temporalio/activity";

export async function runAgent(input: { vmId: string; ticketKey: string }): Promise<string> {
  const ctx = Context.current();
  const last = ctx.info.heartbeatDetails as { sessionId?: string } | undefined;
  const session = last?.sessionId ?? (await startSession(input));
  const timer = setInterval(() => ctx.heartbeat({ sessionId: session }), 10_000);
  try {
    return await waitForPr(session);
  } finally {
    clearInterval(timer);
  }
}

import { Worker } from "@temporalio/worker";
import * as activities from "./activities/index.js";

const worker = await Worker.create({
  workflowsPath: new URL("./workflows/index.js", import.meta.url).pathname,
  activities,
  taskQueue: "nova",
});
await worker.run();
